def refuse_duplicate_areas(apps, schema_editor):
    """ADR-041 decision B: stop, without changing anything, if a Place already has two 3D Areas.

    Nothing is deleted or reassigned automatically: resolve each listed Place by hand (retire and
    move or remove the extra 3D Area, docs/ISLAND_ADVENTURE_MANAGEMENT.md), then migrate again.
    """
    WorldRegion = apps.get_model("regions", "WorldRegion")
    duplicates = (
        WorldRegion.objects.values("location__slug")
        .annotate(areas=Count("id"))
        .filter(areas__gt=1)
        .order_by("location__slug")
    )
    if duplicates:
        report = ", ".join(f"{row['location__slug']} ({row['areas']})" for row in duplicates)
        raise RuntimeError(
            "These Places have more than one 3D Area, so the one-per-Place constraint cannot be "
            f"added: {report}. Nothing was changed."
        )


